(function(){
'use strict';
const KEY='APLUS_P6_PRELIM_SESSION_V2',DONE='APLUS_P6_PRELIM_COMPLETED_V2',TOTAL=6600,VERSION='6.3';
const BP=[
{id:'grammar',name:'BOOKLET A · Grammar',count:10,marks:10,b:'A',kind:'mcq'},
{id:'vocabulary',name:'BOOKLET A · Vocabulary',count:5,marks:5,b:'A',kind:'mcq'},
{id:'vocabularyCloze',name:'BOOKLET A · Vocabulary Cloze',count:5,marks:5,b:'A',kind:'mcq'},
{id:'visual',name:'BOOKLET A · Visual Text',count:5,marks:5,b:'A',kind:'mcq'},
{id:'grammarCloze',name:'BOOKLET B · Grammar Cloze',count:10,marks:10,b:'B',kind:'oe'},
{id:'editing',name:'BOOKLET B · Editing for Spelling and Grammar',count:10,marks:10,b:'B',kind:'oe'},
{id:'comprehensionCloze',name:'BOOKLET B · Comprehension Cloze',count:15,marks:15,b:'B',kind:'oe'},
{id:'synthesis',name:'BOOKLET B · Synthesis and Transformation',count:5,marks:10,b:'B',kind:'oe'},
{id:'comprehension',name:'BOOKLET B · Comprehension',count:10,marks:20,b:'B',kind:'oe'}];
let state={version:VERSION,started:false,submitted:false,index:0,remaining:TOTAL,questions:[],answers:{},candidate:'',className:'',profile:'standard',paperId:'',seed:0};let timer=null;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function db(n){let a=window[n];if(Array.isArray(a))return a;try{a=eval(n);return Array.isArray(a)?a:[]}catch(e){return[]}}
function rng(seed){let x=seed>>>0||1;return()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return(x>>>0)/4294967296}}
function sh(a,r){a=a.slice();for(let i=a.length-1;i;i--){let j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function norm(s){return String(s??'').toLowerCase().replace(/[“”‘’".,!?;:()]/g,' ').replace(/\s+/g,' ').trim()}
function uniq(a){let m=new Map();a.forEach(x=>x&&x.id&&m.set(x.id,x));return[...m.values()]}
function sources(){return{
g:uniq([].concat(db('APLUS_AI_DB_V1_P6_GRAMMAR_QUESTION_BANK'),db('APLUS_AI_DB_V1_GRAMMAR_P6_QUESTION_BANK'),db('APLUS_AI_DB_V1_GRAMMAR_P6_EXPANSION_BATCH02'),db('APLUS_AI_DB_V1_GRAMMAR_P6_EXPANSION_BATCH03'),db('APLUS_AI_DB_V1_GRAMMAR_P6_EXPANSION_BATCH04'),db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_GRAMMAR_BATCH01'))),
v:uniq([].concat(db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_MASTER_VOCABULARY_CONTENT_B03'),db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_VOCABULARY_BATCH02'))),
ce:uniq([].concat(db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_QUESTION_BANK'),db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_EXPANSION_BATCH02'),db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_EXPANSION_BATCH03'),db('APLUS_AI_DB_V1_P6_CLOZE_EDITING_EXPANSION_BATCH04'))),
st:uniq([].concat(db('APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_QUESTION_BANK'),db('APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH02'),db('APLUS_AI_DB_V1_P6_SYNTHESIS_TRANSFORMATION_EXPANSION_BATCH04'))),
comp:uniq([].concat(db('APLUS_AI_DB_V1_P6_COMPREHENSION_QUESTION_BANK'),db('APLUS_AI_DB_V1_P6_COMPREHENSION_EXPANSION_BATCH02'))),
pass:uniq([].concat(db('APLUS_AI_DB_V1_P6_COMPREHENSION_PASSAGE_SETS_BATCH01'),db('APLUS_AI_DB_V1_P6_COMPREHENSION_PASSAGE_SETS_BATCH02'))),
ed:uniq([].concat(db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_MASTER_EDITING_DNA_B03'),db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_EDITING_DNA_BATCH02'))),
vis:uniq(db('APLUS_AI_DB_V1_P6_PSLE_PAPER2_CORE_VISUAL_TEXT_DNA_BATCH01'))}}
function band(p){return({hard:[3,5],vocabularyIntensive:[2,5],grammarIntensive:[2,5],comprehensionIntensive:[2,5],psleSimulation:[2,4],standard:[1,5],studentWeakness:[1,5]})[p]||[1,5]}
function take(a,n,r,used,strict=true){let p=a.filter(x=>x&&(!used||!used.has(x.id))),[lo,hi]=band(state.profile),f=p.filter(x=>{let d=Number(x.difficulty);if(!Number.isFinite(d))d=3;return!strict||d>=lo&&d<=hi});return sh(f.length>=n?f:p,r).slice(0,n)}
function tag(q,d,id){q.sourceDatabase=d;q.sourceRecordId=id;q.generationSeed=state.seed;q.engineVersion=VERSION;return q}
function grammar(S,n,r,used){let out=[];for(let x of take(S.g,n*5,r,used)){if(out.length>=n||!x.question||!Array.isArray(x.options)||x.answer==null)continue;let bad=x.options.filter(o=>norm(o)!==norm(x.answer));if(bad.length<3)continue;let opts=sh([x.answer,...bad.slice(0,3)],r);if(new Set(opts.map(norm)).size!==4)continue;out.push(tag({type:'mcq',marks:1,question:x.question,options:opts,answer:String(x.answer),explanation:x.explanation||'',skill:x.skill||x.topic||'grammar',difficulty:Number(x.difficulty)||3},'P6 Grammar Database',x.id))}return out}
function vocab(S,n,r,used){let out=[];for(let x of take(S.v,n*6,r,used)){if(out.length>=n||!x.word)continue;let clue=x.contextClue||(Array.isArray(x.contextClues)?x.contextClues.join(' '):'The context gives a clear clue to the meaning.');let pool=S.v.map(y=>y.word).filter(w=>w&&norm(w)!==norm(x.word));let d=[...(x.antonyms||[]),...(x.synonyms||[]),...sh(pool,r)];d=[...new Set(d.filter(Boolean).map(String).filter(w=>norm(w)!==norm(x.word)))];if(d.length<3)continue;out.push(tag({type:'mcq',marks:1,question:clue+' Which word best fits the sentence?',options:sh([x.word,...d.slice(0,3)],r),answer:String(x.word),explanation:x.definition||'',skill:'contextual word choice',difficulty:Number(x.difficulty)||3},'P6 Master Vocabulary',x.id))}return out}
function vcloze(S,n,r,used){let out=[];for(let x of take(S.v,n*6,r,used)){if(out.length>=n||!x.word)continue;let clue=x.contextClue||(Array.isArray(x.contextClues)?x.contextClues.join(' '):'The context provides enough information.');let d=sh(S.v.filter(y=>y.word&&norm(y.word)!==norm(x.word)),r).slice(0,3).map(y=>String(y.word));if(d.length<3)continue;out.push(tag({type:'mcq',marks:1,question:clue+' Choose the word that best completes the context.',options:sh([String(x.word),...d],r),answer:String(x.word),explanation:x.definition||'',skill:'vocabulary cloze',difficulty:Number(x.difficulty)||3},'P6 Vocabulary Cloze Database',x.id))}return out}
const VT=[{title:'SCHOOL READING WEEK',rows:[['Monday','Book Swap','3.00–4.00 p.m.','Library','Bring up to three books.'],['Tuesday','Author Talk','2.30–3.30 p.m.','Hall','Sign up by Friday.'],['Wednesday','Storytelling','1.30–2.30 p.m.','Library','Open to P4–P6.'],['Thursday','Bookmark Design','3.00–4.00 p.m.','Art Room','Submit designs by Wednesday.'],['Friday','Reading Challenge','2.00–3.00 p.m.','Hall','Complete a 20-minute reading task.']]},{title:'GREEN CAMPUS DAY',rows:[['Monday','Planting Session','3.00–4.00 p.m.','Garden','Wear covered shoes.'],['Tuesday','Recycling Drive','2.00–3.00 p.m.','Block A','Bring clean recyclables.'],['Wednesday','Water-Saving Talk','1.30–2.15 p.m.','Hall','Open to all pupils.'],['Thursday','Poster Display','2.30–4.00 p.m.','Library','Vote for one poster.'],['Friday','Clean-Up Walk','3.00–4.00 p.m.','Main Gate','Bring gloves.']]}];
function visual(n,r){let t=VT[Math.floor(r()*VT.length)],rows=t.rows,txt='Day | Activity | Time | Venue | Important Information\n'+rows.map(x=>x.join(' | ')).join('\n'),q=[['When is '+rows[1][1]+' held?',[rows[1][2],rows[0][2],rows[2][2],rows[4][2]],rows[1][2]],['Where is '+rows[2][1]+' held?',[rows[2][3],rows[1][3],rows[3][3],rows[0][3]],rows[2][3]],['What instruction applies to '+rows[0][1]+'?',[rows[0][4],rows[1][4],rows[2][4],rows[4][4]],rows[0][4]],['Which activity takes place in the '+rows[3][3]+'?',[rows[3][1],rows[0][1],rows[1][1],rows[4][1]],rows[3][1]],['Which statement is supported by the visual text?',[rows[3][1]+' requires designs by Wednesday.',rows[4][1]+' is held in the Library.',rows[1][1]+' is open only to P4–P6.',rows[0][1]+' is held in the Hall.'],rows[3][1]+' requires designs by Wednesday.']];return q.slice(0,n).map((x,i)=>tag({type:'mcq',marks:1,visual:{title:t.title,text:txt},question:x[0],options:sh(x[1],r),answer:x[2],explanation:'The answer is supported by the visual text.',skill:'visual text',difficulty:2},'P6 Visual Text Database','VIS-'+t.title+'-'+i))}
function cloze(S,n,r,used){let out=[];for(let x of take(S.ce.filter(x=>x.type==='cloze'&&x.answer!=null&&x.text),n*4,r,used,false)){if(out.length>=n)break;let text=String(x.text),ans=String(x.answer);if(!/___|__+|\[blank\]/.test(text)){let re=new RegExp(ans.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));text=text.replace(re,'___')}if(!text.includes('___'))continue;out.push(tag({type:'oe',marks:1,passage:text,question:'Fill in the blank with the most suitable word.',answer:ans,acceptedPatterns:[ans],explanation:x.explanation||'',skill:x.skill||'cloze',difficulty:Number(x.difficulty)||3},'P6 Cloze Database',x.id))}return out}
function editing(S,n,r,used){let pool=S.ed.filter(x=>x.original&&x.corrected&&norm(x.original)!==norm(x.corrected)),out=[];for(let x of take(pool,n*3,r,used,false)){if(out.length>=n)break;out.push(tag({type:'oe',marks:1,passage:String(x.original),question:'Correct the error in the sentence. Write the corrected sentence.',answer:String(x.corrected),acceptedPatterns:[String(x.corrected)],explanation:x.rule||x.explanation||'',skill:x.errorType||'editing',difficulty:Number(x.difficulty)||3},'P6 Editing DNA',x.id))}if(out.length<n)for(let x of take(S.ce.filter(x=>x.type==='editing'&&x.text&&x.answer!=null),n*3,r,used,false)){if(out.length>=n)break;out.push(tag({type:'oe',marks:1,passage:String(x.text),question:'Correct the sentence.',answer:String(x.answer),acceptedPatterns:[String(x.answer)],explanation:x.explanation||'',skill:x.skill||'editing',difficulty:Number(x.difficulty)||3},'P6 Editing Database',x.id))}return out}
function synth(S,n,r,used){return take(S.st.filter(x=>x.question&&x.answer!=null),n*3,r,used,false).map(x=>tag({type:'oe',marks:2,question:String(x.question),answer:String(x.answer),acceptedPatterns:x.acceptedPatterns||[String(x.answer)],explanation:x.explanation||'',skill:x.skill||'synthesis',difficulty:Number(x.difficulty)||3},'P6 Synthesis and Transformation Database',x.id)).slice(0,n)}
function comp(S,n,r,used){let out=[];for(let p of sh(S.pass,r)){let qs=Array.isArray(p.questions)?sh(p.questions,r):[];for(let q of qs){if(out.length>=n||!q.question)break;let a=q.answer;if(typeof a==='number'&&Array.isArray(q.options))a=q.options[a];if(a==null)continue;let passage=String(p.text||p.passage||'');if(!passage)continue;out.push(tag({type:'oe',marks:2,passage,question:String(q.question),answer:String(a),acceptedPatterns:[String(a)],explanation:q.explanation||'',skill:q.skill||q.type||'comprehension',difficulty:Number(q.difficulty)||3},'P6 Comprehension Passage Sets',(p.passageId||p.id)+'::'+(q.id||q.question)))}}if(out.length<n)for(let q of take(S.comp.filter(x=>x.question&&x.answer!=null&&x.passage),n*2,r,used,false)){if(out.length>=n)break;out.push(tag({type:'oe',marks:2,passage:String(q.passage),question:String(q.question),answer:String(q.answer),acceptedPatterns:[String(q.answer)],explanation:q.explanation||'',skill:q.skill||q.type||'comprehension',difficulty:Number(q.difficulty)||3},'P6 Comprehension Question Bank',q.id))}return out.slice(0,n)}
function build(){let S=sources(),r=rng(state.seed),all=[];const makers={grammar:()=>grammar(S,10,r,new Set()),vocabulary:()=>vocab(S,5,r,new Set()),vocabularyCloze:()=>vcloze(S,5,r,new Set()),visual:()=>visual(5,r),grammarCloze:()=>cloze(S,10,r,new Set()),editing:()=>editing(S,10,r,new Set()),comprehensionCloze:()=>cloze(S,15,r,new Set()),synthesis:()=>synth(S,5,r,new Set()),comprehension:()=>comp(S,10,r,new Set())};for(let b of BP){let need=b.count,a=makers[b.id](),guard=0;while(a.length<need&&guard++<5){let more=makers[b.id]();for(let q of more){if(a.length>=need)break;q=Object.assign({},q,{sourceRecordId:q.sourceRecordId+'#'+a.length});a.push(q)}}if(a.length<need)return[];for(let q of a.slice(0,need)){q.number=all.length+1;q.id='Q'+q.number;q.section=b.id;q.sectionName=b.name;q.booklet=b.b;q.marks=(b.id==='synthesis'||b.id==='comprehension')?2:1;all.push(q)}}return all}
function validate(q){let marks=q.reduce((s,x)=>s+x.marks,0);if(q.length!==75||marks!==90)return false;for(let b of BP){let a=q.filter(x=>x.section===b.id);if(a.length!==b.count)return false;for(let x of a){if(!x.question||!x.sourceRecordId)return false;if(x.type==='mcq'){if(!Array.isArray(x.options)||x.options.length!==4||!x.options.includes(x.answer))return false}else if(!x.answer)return false;if(['grammarCloze','editing','comprehensionCloze','comprehension'].includes(x.section)&&!x.passage)return false}}return true}
function generate(){for(let i=0;i<20;i++){state.seed=(Date.now()+Math.floor(Math.random()*0xffffffff)+i*7919)>>>0;let q=build();if(validate(q))return q}return[]}
function show(id){document.querySelectorAll('.screen').forEach(x=>x.classList.remove('active'));$(id).classList.add('active')}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}}
function time(x){x=Math.max(0,Math.floor(x));return String(Math.floor(x/3600)).padStart(2,'0')+':'+String(Math.floor(x%3600/60)).padStart(2,'0')+':'+String(x%60).padStart(2,'0')}
function usableSaved(s){if(!s||!Array.isArray(s.questions)||s.questions.length!==75)return false;return s.questions.every(q=>q&&q.question&&q.sourceRecordId&&(q.type==='mcq'?Array.isArray(q.options)&&q.options.length===4:['grammarCloze','editing','comprehensionCloze','comprehension'].includes(q.section)?!!q.passage:!!q.question))}
function nav(){let box=$('sectionNav');box.innerHTML='';BP.forEach(b=>{let h=document.createElement('div');h.className='nav-section';h.innerHTML='<div class="nav-section-title">'+esc(b.name)+'</div>';state.questions.forEach((q,i)=>{if(q.section===b.id){let x=document.createElement('button');x.className='nav-q '+(state.answers[q.number]?'answered ':'')+(i===state.index?'current':'');x.textContent=q.number;x.onclick=()=>{state.index=i;save();render()};h.appendChild(x)}});box.appendChild(h)})}
function render(){let q=state.questions[state.index];if(!q)return;let b=BP.find(x=>x.id===q.section);$('bookletLabel').textContent='BOOKLET '+q.booklet;$('sectionLabel').textContent=b.name.replace('BOOKLET A · ','').replace('BOOKLET B · ','');$('progressText').textContent='Question '+q.number+' of 75';$('progressBar').style.width=(q.number/75*100)+'%';$('markText').textContent=q.marks+' '+(q.marks===1?'mark':'marks');let h='<div class="q-kicker">'+esc(q.sectionName)+'</div><h2>Question '+q.number+'</h2>';if(q.visual)h+='<div class="visual"><strong>'+esc(q.visual.title)+'</strong><pre>'+esc(q.visual.text)+'</pre></div>';if(q.passage)h+='<div class="passage">'+esc(q.passage)+'</div>';h+='<div class="question-text">'+esc(q.question)+'</div>';if(q.type==='mcq')h+='<div class="options">'+q.options.map((o,i)=>'<label class="option"><input type="radio" name="q" value="'+esc(o)+'" '+(norm(state.answers[q.number])===norm(o)?'checked':'')+'><span class="letter">'+String.fromCharCode(65+i)+'.</span><span>'+esc(o)+'</span></label>').join('')+'</div>';else h+='<textarea id="oeAnswer" placeholder="Type your answer here">'+esc(state.answers[q.number]||'')+'</textarea>';$('questionCard').innerHTML=h;document.querySelectorAll('input[name=q]').forEach(x=>x.onchange=()=>{state.answers[q.number]=x.value;save();nav()});let ta=$('oeAnswer');if(ta)ta.oninput=()=>{state.answers[q.number]=ta.value;save()};$('prevBtn').disabled=state.index===0;$('nextBtn').textContent=state.index===74?'FINISH':'Next';nav()}
function tick(){if(!state.started||state.submitted)return;if(--state.remaining<=0){state.remaining=0;save();submit(true)}$('timer').textContent=time(state.remaining);if(state.remaining%5===0)save()}
function grade(q,a){let n=norm(a);if(!n)return 0;let acc=(q.acceptedPatterns||[q.answer]).map(norm);if(acc.includes(n))return q.marks;if(q.type==='oe'&&q.marks===2){let k=norm(q.answer).split(' ').filter(x=>x.length>3),hits=k.filter(x=>n.includes(x)).length;if(k.length&&hits>=Math.ceil(k.length*.75))return 2;if(k.length&&hits>=Math.ceil(k.length*.35))return 1}return 0}
function result(auto){let score=0;state.questions.forEach(q=>{q.awarded=grade(q,state.answers[q.number]);score+=q.awarded});state.score=score;state.percentage=Math.round(score/90*100);state.submitted=true;state.submittedAt=new Date().toISOString();clearInterval(timer);try{localStorage.setItem(DONE,JSON.stringify(state));localStorage.removeItem(KEY)}catch(e){}$('paperId').textContent=state.paperId+' · '+state.candidate;$('score').textContent=score+' / 90';$('percentage').textContent=state.percentage+'%';$('resultMessage').textContent=auto?'Time is up. The paper has been submitted automatically.':state.percentage>=80?'Strong progress.':state.percentage>=50?'More practice is needed in selected areas.':'Let’s rebuild the basics step by step.';let html='<h3>Section Results</h3>';BP.forEach(b=>{let a=state.questions.filter(q=>q.section===b.id),s=a.reduce((v,q)=>v+(q.awarded||0),0);html+='<div class="result-row"><span>'+esc(b.name)+'</span><strong>'+s+' / '+b.count+'</strong></div>'});$('sectionResults').innerHTML=html;show('result')}
function submit(auto){result(auto)}
function start(){state={version:VERSION,started:true,submitted:false,index:0,remaining:TOTAL,questions:[],answers:{},candidate:($('candidateName').value||'').trim(),className:($('candidateClass').value||'').trim(),profile:$('paperProfile').value||'standard',paperId:'',seed:0};state.questions=generate();if(!validate(state.questions)){alert('Paper generation is temporarily unavailable. Please refresh and try again.');state.questions=[];state.started=false;return}state.paperId='APLUS-P6-ENG-P2-'+new Date().getFullYear()+'-'+String(state.seed).padStart(10,'0');save();show('exam');$('timer').textContent=time(TOTAL);clearInterval(timer);timer=setInterval(tick,1000);render()}
function bind(){try{let raw=localStorage.getItem(KEY);if(raw){let x=JSON.parse(raw);if(usableSaved(x)){state=Object.assign(state,x);$('resumeBtn').classList.remove('hidden');$('resumeBtn').onclick=()=>{show('exam');clearInterval(timer);timer=setInterval(tick,1000);render()}}else localStorage.removeItem(KEY)}}catch(e){localStorage.removeItem(KEY)}$('startBtn').onclick=start;$('prevBtn').onclick=()=>{if(state.index){state.index--;save();render()}};$('nextBtn').onclick=()=>{if(state.index<74){state.index++;save();render()}else{$('submitSummary').innerHTML='<p><strong>'+Object.values(state.answers).filter(x=>String(x).trim()).length+' / 75</strong> questions answered.</p>';show('submitScreen')}};$('confirmSubmitBtn').onclick=()=>submit(false);$('backToExamBtn').onclick=()=>{show('exam');render()};$('reviewBtn').onclick=()=>{show('exam');state.index=0;render()};$('printBtn').onclick=()=>window.print();$('newExamBtn').onclick=()=>{localStorage.removeItem(DONE);localStorage.removeItem(KEY);state={version:VERSION,started:false,submitted:false,index:0,remaining:TOTAL,questions:[],answers:{},candidate:'',className:'',profile:'standard',paperId:'',seed:0};show('landing')}}
window.APLUS_P6_PRELIM_V63={BLUEPRINT:BP,sources,generate,getState:()=>state};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
})();
